#include <stdio.h>
#include <string.h> 
// Assuming http_server.h or similar is included in the project for response functions
#include "http_server.h"

/**
 * @brief Handles requests to the /health endpoint.
 * 
 * @param response The response object to populate.
 */
void handle_health_check(HttpResponse* response) {
    const char* body = "{\"status\": \"ok\"}";
    response->status_code = 200;
    strncpy(response->content_type, "application/json", sizeof(response->content_type) - 1);
    strncpy(response->body, body, sizeof(response->body) - 1);
    response->body_len = strlen(body);
}
```

